'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var PI = require( '@stdlib/constants/float64/pi' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );


// MAIN //

/**
* Returns the skewness of a half-normal distribution with scale parameter `sigma`.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} skewness
*
* @example
* var y = skewness( 1.0 );
* // returns ~0.995
*
* @example
* var y = skewness( 4.0 );
* // returns ~0.995
*
* @example
* var y = skewness( NaN );
* // returns NaN
*
* @example
* var y = skewness( -1.0 );
* // returns NaN
*/
function skewness( sigma ) {
	if ( isnan( sigma ) || sigma < 0.0 ) {
		return NaN;
	}
	// Skewness = (sqrt(2) * (4 - PI)) / (PI - 2)^(3/2)
	return ( SQRT2 * ( 4.0 - PI ) ) / pow( PI - 2.0, 1.5 );
}


// EXPORTS //

module.exports = skewness;
